  "definition": "A fan with RRF > 3.5, lastlogdt more than 20 days in the past, and engrate < 0.2, requiring immediate retention efforts."
}

{
  "id": 13,
  "knowledge": "Retention Risk Factor (RRF)",
  "description": "Quantifies the risk of fan churn based on multiple behavioral indicators",
  "definition": "RRF = (1 - intconsist) \\times 2 + \\left(\\frac{CURRENT\\_DATE - lastlogdt}{30}\\right) \\times 0.5 + \\left(\\frac{churnflag\\_numeric}{3}\\right) \\times 2, \\text{ where churnflag\\_numeric maps churnflag enum: None=0, Low=1, Medium=2, High=3.}"
}

